/* THE_SIDEREAL_PASSAGE_BEGIN */
// The cloister wall and the library share a boundary. The old chapter-house route
// remains open, while the two pierced bronze dials reveal a shortcut between them.
(() => {
  const column = 77, row = 43, doorKey = "77,43";
  const centre = (column + .5) * P, face = (row + 1) * P;
  const dialOffsets = [-2.72,2.72], dialHeight = 1.30, dialDepth = .38;
  const starts = [0,2], targets = [3,0];
  const quarter = Math.PI / 2;
  let live = null;
  const build = gV[9].build;
  gV[9].build = function (...args) {
    const map = build.apply(this,args);
    for (let z = row-2; z <= row; z++) {
      map.g[z][column] = z === row ? "S" : ".";
      map.hmap[z][column] = 1.2;
      map.cmap[z][column] = 4.2;
    }
    // Move the same cloister torch clear of the doorway, retaining its light budget.
    map.g[row+1][column] = ".";
    map.g[row+1][column-3] = "i";
    return map;
  };

  const atlas = /* SIDEREAL_ATLAS_BEGIN */ {"colors":"","tiles":[["portal",2,2,222,275,""],["moonBezel",226,2,134,153,""],["starBezel",376,2,134,153,""],["moonHand",227,158,46,51,""],["starHand",276,158,49,49,""]]} /* SIDEREAL_ATLAS_END */;
  function carvings() {
    const palette = atob(atlas.colors);
    const tex = Z(e0(ctx => {
      const pixels = ctx.createImageData(512,512);
      for (const [,left,top,w,h,encoded] of atlas.tiles) {
        const indices = atob(encoded);
        for (let y=0; y<h; y++) for (let x=0; x<w; x++) {
          const id=indices.charCodeAt(y*w+x);
          if (!id) continue;
          const i=((top+y)*512+left+x)*4;
          for (let c=0;c<3;c++) pixels.data[i+c]=palette.charCodeAt(3*id+c);
          pixels.data[i+3]=255;
        }
      }
      ctx.putImageData(pixels,0,0);
    },512,512));
    tex.name="siderealCarvings";
    tex.colorSpace=ha;
    tex.generateMipmaps=true;
    tex.minFilter=Yh;
    // A single cutout atlas shares a draw batch across all stationary reliefs.
    return Z(new $e({map:tex,alphaTest:.48,toneMapped:false}));
  }

  function buildPassage(scene,door) {
    const floor=ie(centre,face+.6);
    const frame=new n0();
    frame.name="siderealPassage"; frame.position.set(centre,floor,face); scene.add(frame);
    const art=carvings(), stone=Z(iR("prologuePatinatedStone")), bronze=Z(iR("hellBronze"));
    const red=Z(new $e({map:Ft.wood,color:0x7a4239,toneMapped:false}));
    const iron=Z(new $e({map:Ft.pillar,color:0x71686b,toneMapped:false}));
    const timber=Z(new $e({map:Ft.wood,color:0x785747,toneMapped:false}));
    // Short leather spines have their own grain and raised bands. Wall-sized
    // timber grain loses the binding and looks like a stack of pale boards.
    const bindings=[[112,50,39],[130,94,55],[49,78,82],[87,61,71]].map(rgb=>{
      const tex=Z(e0(ctx=>{
        const pixels=ctx.createImageData(20,64);
        for(let y=0;y<64;y++)for(let x=0;x<20;x++){
          const grain=(((x*71+y*37+x*y*13)^(x*7+y*11))%17)-8;
          const spine=.58+.42*Math.sin(Math.PI*x/19);
          const band=[7,14,48,55].includes(y) && x>1 && x<18;
          const label=y>=24 && y<=33 && x>3 && x<16;
          const gold=band || (label && (y===25 || y===31 || x===5 || x===14));
          for(let c=0;c<3;c++)pixels.data[(y*20+x)*4+c]=(gold?[186,145,86][c]:rgb[c]*(label?.46:1))*spine+grain;
          pixels.data[(y*20+x)*4+3]=255;
        }
        ctx.putImageData(pixels,0,0);
      },20,64));
      tex.colorSpace=ha;return Z(new $e({map:tex,toneMapped:false}));
    });
    const amber=Z(new $e({color:0xf4ba65,toneMapped:false}));
    const gold=Z(new $e({color:0xd4a85b,toneMapped:false}));
    const silver=Z(new $e({color:0xcec5ac,toneMapped:false}));
    const dark=Z(new $e({color:0x2f2928,toneMapped:false}));
    const batch=new Map();
    const box=(mat,w,h,d,x,y,z,angle=0)=>Yd(batch,mat,new Ne(w,h,d),E(x,y,z,0,0,angle));
    const disc=(mat,r,d,x,y,z,n=16)=>Yd(batch,mat,new Eo(r,r,d,n),E(x,y,z,Math.PI/2));
    function beam(mat,x1,y1,x2,y2,width,depth,z) {
      const dx=x2-x1,dy=y2-y1;
      box(mat,width,Math.hypot(dx,dy),depth,(x1+x2)/2,(y1+y2)/2,z,-Math.atan2(dx,dy));
    }
    function flush(parent) {
      for (const [mat,pieces] of batch) parent.add(new pt(Z(BR(pieces)),mat));
      batch.clear();
    }
    function relief(name,w,h,x,y,z,angle=0) {
      const [,left,top,sw,sh]=atlas.tiles.find(t=>t[0]===name);
      const geo=new Xe(w,h),uv=geo.getAttribute("uv");
      for (let i=0;i<uv.count;i++) uv.setXY(i,(left+uv.getX(i)*sw)/512,1-(top+(1-uv.getY(i))*sh)/512);
      Yd(batch,art,geo,E(x,y,z,0,0,angle));
    }

    // Stone jambs, recessed painted panels and deep skewbacks around an open pointed arch.
    for (const side of [-1,1]) {
      const x=side*1.24;
      box(stone,.46,1.76,.46,x,.88,-.02);
      box(stone,.55,.21,.54,x,.11,.02);
      box(red,.21,1.20,.11,x,.91,.23);
      box(stone,.55,.18,.55,x,1.68,.02);
      const profile=[[1.222,1.66],[1.175,1.91],[1.018,2.17],[.77,2.46],[.45,2.74],[0,3.04]];
      for (let i=1;i<profile.length;i++) {
        const [a,b]=profile[i-1],[c,d]=profile[i];
        beam(stone,side*a,b,side*c,d,.41,.44,-.03);
        beam(bronze,side*(a-.13),b-.04,side*(c-.13),d-.04,.035,.05,.22);
      }
    }
    box(stone,3.00,.71,.49,0,3.41,-.02);
    box(stone,3.16,.12,.56,0,3.83,-.02);
    relief("portal",3.15,3.91,0,1.97,.285);

    // The clue is part of the fixed attic, with a pale western and gilt northern
    // witness outside the corresponding symbol. Matching witnesses mark the dials.
    const fixed=[
      {x:-.742,dx:-.28,dy:0,mat:silver},
      {x: .750,dx:0,dy:.30,mat:gold}
    ];
    for (const {x,dx,dy,mat} of fixed) {
      disc(dark,.091,.032,x+dx,3.505+dy,.314,8);
      box(mat,.092,.092,.034,x+dx,3.505+dy,.34,Math.PI/4);
    }
    for(let i=0;i<2;i++){
      const x=dialOffsets[i],type=i===0?"moonBezel":"starBezel";
      disc(dark,.88,.27,x,dialHeight,.02,20);
      disc(bronze,.84,.12,x,dialHeight,.19,24);
      relief(type,2.18,2.49,x,dialHeight-.028,.29);
      const wx=x+(i===0?-.59:0),wy=dialHeight+(i===1?.59:0);
      disc(dark,.082,.033,wx,wy,.304,8);
      box(i===0?silver:gold,.095,.095,.025,wx,wy,.33,Math.PI/4);
    }

    // Paired bands catch the light farther down the actual passage. Their footings
    // stay outside its walkable width and their crowns clear a standing player.
    for (const z of [-1.60,-3.68,-5.57]) {
      for (const side of [-1,1]) {
        box(stone,.075,2.82,.19,side*.98,1.41,z);
        beam(stone,side*.97,2.37,side*.62,2.76,.115,.20,z);
        beam(stone,side*.62,2.76,0,2.96,.115,.20,z);
        box(bronze,.09,.11,.22,side*.966,2.28,z);
      }
    }

    // The inner face belongs to a working scriptorium. Low fitted book-presses
    // flank the way out; their shelf lips never intrude on the door's central aisle.
    for(const side of [-1,1]){
      const x=side*1.93;
      box(timber,1.67,2.06,.16,x,1.03,-6.13);
      for(const edge of [-.82,.82]){
        box(timber,.14,2.19,.32,x+edge,1.095,-6.19);
        box(bronze,.059,1.92,.06,x+edge,1.12,-6.379);
        box(timber,.20,.16,.40,x+edge,.09,-6.2);
        box(timber,.20,.12,.40,x+edge,2.095,-6.2);
      }
      for(const y of [.21,.86,1.48,2.10]){
        box(timber,1.82,.085,.41,x,y,-6.23);
        box(bronze,1.78,.028,.035,x,y-.035,-6.448);
      }
      const widths=[.13,.15,.105,.145,.095,.15,.12,.16,.11,.105];
      for(let row=0;row<3;row++){
        let dx=-.73;
        for(let i=0;i<widths.length;i++){
          const w=widths[(i+row)%widths.length],h=.32+((i*7+row*3+(side+1))%8)*.028;
          const bookX=x+dx+w/2,y=.256+row*.63+h/2;
          const tilt=i===9?.10*side:0;
          box(bindings[(row+i+(side+1))%4],w-.014,h,.23,bookX,y,-6.29,tilt);
          dx+=w;
        }
      }
      box(stone,.21,2.48,.36,side*1.04,1.24,-6.12);
      beam(stone,side*1.02,2.39,side*.61,2.80,.19,.32,-6.14);
      beam(stone,side*.61,2.80,0,3.06,.18,.32,-6.14);
    }
    // A suspended armillary over the library threshold makes a three-dimensional
    // destination visible down the arch. The rings hang above walking height.
    const ax=.21,ay=2.43,az=-8.35;
    for(const [radius,rx,ry,rz,metal] of [[.47,0,0,0,bronze],[.42,.56,.87,.38,gold],[.46,1.24,-.42,.16,bronze]]){
      Yd(batch,metal,new Hu(radius,.028,5,24),E(ax,ay,az,rx,ry,rz));
    }
    box(iron,.035,3.0,.035,ax,4.36,az);
    box(bronze,.065,.30,.065,ax,2.96,az);
    Yd(batch,amber,new Eo(0,.17,.28,8),E(ax,ay+.14,az));
    Yd(batch,gold,new Eo(.17,0,.22,8),E(ax,ay-.11,az));
    // The amber reading lantern is self-lit. A small pool in the tiles and a
    // warm reflection on the bindings make the library legible without a point light.
    box(iron,.55,.07,.14,-.82,2.25,-5.28);
    box(iron,.032,.21,.035,-.57,2.13,-5.28);
    box(amber,.13,.22,.13,-.57,1.92,-5.28);
    for(const [w,y] of [[.23,2.045],[.21,1.80]])box(bronze,w,.056,w,-.57,y,-5.28);
    for(const x of [-.64,-.50])for(const z of [-5.35,-5.21])box(iron,.021,.23,.021,x,1.92,z);
    for(let i=0;i<7;i++){
      const x=(i%2===0?.26:-.29);
      box(i===4?bronze:stone,.86,.016,.72,x,.013,-.55-i*.75);
      // Worn diagonal inlays catch the player light between bays. Stop them
      // short of the threshold so they emerge from behind the descending grate.
      if(i===0 || i===2 || i===4 || i===6){
        for(const side of [-1,1]){
          const inlay=side<0?gold:bronze;
          Yd(batch,inlay,new Ne(.33,.015,.045),E(side*.125,.030,-.68-i*.75,0,-side*.43));
        }
      }
    }
    flush(frame);

    const hands=[],witnesses=[];
    for(let i=0;i<2;i++){
      const pivot=new n0();
      pivot.name=i===0?"siderealMoon":"siderealStar";
      pivot.position.set(dialOffsets[i],dialHeight,dialDepth);
      frame.add(pivot);
      box(bronze,.082,.34,.055,0,.215,-.025);
      relief(i===0?"moonHand":"starHand",i===0?.58:.63,i===0?.64:.63,0,.352,.025,
        i===0?.25*Math.PI:0);
      disc(bronze,.115,.082,0,0,.025);
      disc(i===0?silver:gold,.065,.036,0,0,.080,12);
      flush(pivot);
      hands.push(pivot);
      // A second, stationary ring lights around the matching witness as a bolt seats.
      const catchRing=new n0();
      catchRing.position.set(dialOffsets[i]+(i===0?-.59:0),dialHeight+(i===1?.59:0),.34);
      for(const bend of [-1,1]){
        beam(i===0?silver:gold,-.10,0,0,bend*.10,.029,.032,.010);
        beam(i===0?silver:gold,0,bend*.10,.10,0,.029,.032,.010);
      }
      flush(catchRing);frame.add(catchRing);catchRing.visible=false;
      witnesses.push(catchRing);
    }

    // The native door owns collision, save facts and descent. Its grate admits
    // real views through the unfinished library rather than drawing a background.
    door.mesh.material=Z(new $e({visible:false}));
    const grate=new n0();
    grate.name="siderealPortcullis";
    grate.position.set(0,-door.h/2,.88);
    door.mesh.add(grate);
    for(const x of [-.95,-.64,-.33,0,.33,.64,.95]) {
      const height=2.78-.94*Math.pow(Math.abs(x),1.55);
      box(x===0?red:iron,x===0?.093:.046,height,.072,x,height*.5,0);
      if(x!==0) box(bronze,.061,.061,.084,x,1.14,.010,Math.PI/4);
    }
    for(const y of [.13,.80,1.48])box(iron,1.95,.055,.066,0,y,-.012);
    for(const base of [-1.62,-.92,-.22,.48,1.18,1.88,2.58]){
      for(const side of [-1,1]){
        const start=Math.max(-.95,-base+.10),end=Math.min(.95,(2.60-base)*.67);
        if(end>start+.04)beam(bronze,side*start,base+start,side*end,base+end,.029,.041,.045);
      }
    }
    flush(grate);
    return {door,hands,witnesses,floor,steps:starts.slice(),angles:starts.map(v=>-v*quarter),hint:-1,turning:false};
  }

  const decorate=FJ;
  FJ=function(scene,map) {
    live=null;
    decorate(scene,map);
    if(T.level!==9 || !v.doors[doorKey])return;
    live=buildPassage(scene,v.doors[doorKey]);
    live.hands.forEach((p,i)=>p.rotation.z=live.angles[i]);
  };

  // An E aimed at the closed gate gives the same clue from either approach.
  // The native two-seal gate, lift lever, bell niches and one-way routes keep their rules.
  const gateRule=KH;
  KH=function(x,z) {
    if(live && x===column && z===row && !live.door.open)
      return {gate:false,block:"THE MOON SETS WEST. THE STAR KEEPS NORTH."};
    return gateRule.apply(this,arguments);
  };
  function aimedDial(){
    if(!live || live.door.open || C.pz<face+.27 || C.pz>face+2.78 ||
        Math.abs(C.px-centre)>4.9 || !Be.started || Be.inputLock || T.dead || T.won ||
        oo.busy || Wk() || Qm())return -1;
    const dz=face+dialDepth-C.pz;
    for(let i=0;i<2;i++){
      const dx=centre+dialOffsets[i]-C.px,dy=live.floor+dialHeight-C.pyy;
      const range=Math.hypot(dx,dy,dz);
      if(range>.01 && range<2.50 && (-Math.sin(Ct.yaw)*Math.cos(Ct.pitch)*dx+
          Math.sin(Ct.pitch)*dy-Math.cos(Ct.yaw)*Math.cos(Ct.pitch)*dz)/range>.916)return i;
    }
    return -1;
  }
  function chime(i,aligned) {
    Nt(centre+dialOffsets[i],live.floor+dialHeight,face+.4,()=>nt("churchBells",()=>{
      const f=i===0?220:330;
      const notes=[{tone:"triangle",f:f*.5,env:{a:.004,d:.105},level:.12},
        {at:.046,tone:"sine",f:aligned?f*2:f*1.505,env:{a:.002,d:aligned?.62:.20},level:.13}];
      if(live.door.open)notes.push({at:.21,tone:"sine",f:440,env:{a:.080,d:1.65},level:.15},
        {at:.38,tone:"sine",f:659.25,env:{a:.080,d:1.75},level:.095});
      gt(notes);
    }));
  }
  const interact=N$;
  N$=function(...args) {
    const i=aimedDial();
    if(i<0 || Rk())return interact.apply(this,args);
    live.steps[i]=(live.steps[i]+1)%4;
    live.angles[i]-=quarter;
    live.turning=true;
    const aligned=live.steps[i]===targets[i];
    live.witnesses[i].visible=aligned;
    if(live.steps.every((v,j)=>v===targets[j])) {
      live.door.open=true;
      T.secrets++; T.totSecrets++;
      w0("secret",true);
      if(T.totSecrets===2)mn(gn.curious,T.ach);
      Nt(centre,live.floor+dialHeight,face,()=>MV("gate"));
      hr(centre,face,8);
      le("SECRET FOUND — THE LIBRARY PASSAGE OPENS",3.2);
    } else {
      const name=i===0?"MOON":"STAR",bearing=["NORTH","EAST","SOUTH","WEST"][live.steps[i]];
      le(name+" · "+bearing+(aligned?" — ALIGNED":"  [E] TURN"),1.6);
    }
    chime(i,aligned);
  };

  const update=F$;
  F$=function(dt) {
    update(dt);
    if(!live)return;
    if(live.turning){
      live.turning=false;
      live.hands.forEach((hand,i)=>{
        const d=live.angles[i]-hand.rotation.z;
        if(Math.abs(d)<.003){hand.rotation.z=live.angles[i];return;}
        hand.rotation.z+=d*(1-Math.exp(-Math.max(0,dt)*14));
        live.turning=true;
      });
    }
    const i=aimedDial();
    if(i<0)live.hint=-1;
    else if(i!==live.hint && mf<=0){
      le(i===0?"[E] TURN MOON — THE MOON SETS WEST":"[E] TURN STAR — THE STAR KEEPS NORTH",2.0);
      live.hint=i;
    }
  };

  const capture=FX,restore=a_;
  FX=function() {
    const facts=capture.apply(this,arguments);
    if(live) facts.sidereal=live.steps.slice();
    return facts;
  };
  a_=function(facts) {
    restore.apply(this,arguments);
    if(!live)return;
    const saved=live.door.open?targets:facts.sidereal;
    if(!Array.isArray(saved)||saved.length!==2 || !saved.every(n=>Number.isInteger(n)&&n>=0&&n<=3))return;
    live.steps=saved.slice(); live.angles=saved.map(n=>-n*quarter); live.turning=false;
    live.hands.forEach((h,i)=>h.rotation.z=live.angles[i]);
    live.witnesses.forEach((w,i)=>w.visible=saved[i]===targets[i]);
  };
})();
/* THE_SIDEREAL_PASSAGE_END */
